const delay=document.querySelector(".swiper.mySwiper").dataset.swiperDelay,swiper=new Swiper(".mySwiper",{grabCursor:!0,slidesPerView:1,autoHeight:!0,autoplay:{delay:Number(delay),disableOnInteraction:!1},navigation:{nextEl:".swiper-button-next",prevEl:".swiper-button-prev"},pagination:{el:".swiper-pagination",clickable:!0}});document.addEventListener("click",e=>{const t=e.target.closest(".wrapper-input>.btn-icon");if(!t)return;const r=t.closest(".wrapper-input").querySelector("input");r.type="password"===r.type?"text":"password",t.classList.toggle("active")});